Rva0093FD80Iterator Rva0093DCE0Tree::insert(
    _STL::_Rb_tree_node_base *x, _STL::_Rb_tree_node_base *y,
    const Rva0093FD80Value &value, _STL::_Rb_tree_node_base *w)
{
    Rva0093DCE0Node *z;
    if (y == header.node || (w == 0 && (x != 0 || value.key < key(y))))
    {
        z = create(value);
        y->_M_left = z;
        if (y == header.node)
        {
            header.node->_M_parent = z;
            header.node->_M_right = z;
        }
        else if (y == header.node->_M_left)
            header.node->_M_left = z;
    }
    else
    {
        z = create(value);
        y->_M_right = z;
        if (y == header.node->_M_right)
            header.node->_M_right = z;
    }
    z->_M_parent = y;
    z->_M_left = 0;
    z->_M_right = 0;
    _STL::_Rb_global<bool>::_Rebalance(z, header.node->_M_parent);
    ++count;
    return Rva0093FD80Iterator(z);
}

// Control flow follows the shipped STLport insertion algorithm; the value
// and owning node declarations above are independently reconstructed.
Rva0093FE40Result Rva0093DCE0Tree::insertUnique(const Rva0093FD80Value &__v)
{
  _STL::_Rb_tree_node_base * __y = header.node;
  _STL::_Rb_tree_node_base * __x = header.node->_M_parent;
  bool __comp = true;
  while (__x != 0) {
    __y = __x;
    __comp = (__v.key < key(__x));
    __x = __comp ? __x->_M_left : __x->_M_right;
  }
  Rva0093FD80Iterator __j = Rva0093FD80Iterator(__y);

  if (__comp && __j.node == header.node->_M_left)
    return Rva0093FE40Result(insert(__y, __y, __v), true);
  if (__comp)
    --__j;

  if ((key(__j.node) < __v.key))
    return Rva0093FE40Result(insert(__x, __y, __v), true);
  return Rva0093FE40Result(__j, false);
}
Rva0093FD80Iterator Rva0093DCE0Tree::insertUnique(Rva0093FD80Iterator __position,
    const Rva0093FD80Value &__v)
{
  if (__position.node == header.node->_M_left) { // begin()

    // if the container is empty, fall back on insert_unique.
    if (count <= 0)
      return insertUnique(__v).first;

    if ( _STL::less<unsigned short>()(__v.key, key(__position.node)))
      return insert(__position.node, __position.node, __v);
    // first argument just needs to be non-null
    else
      {
	bool __comp_pos_v = _STL::less<unsigned short>()(key(__position.node), __v.key);

	if (__comp_pos_v == false)  // compare > and compare < both false so compare equal
	  return __position;
	//Below __comp_pos_v == true

	// Standard-conformance - does the insertion point fall immediately AFTER
	// the hint?
	Rva0093FD80Iterator __after = __position;
	++__after;

	// Check for only one member -- in that case, __position points to itself,
	// and attempting to increment will cause an infinite loop.
	if (__after.node == header.node)
	  // Check guarantees exactly one member, so comparison was already
	  // performed and we know the result; skip repeating it in _M_insert
	  // by specifying a non-zero fourth argument.
	  return insert(0, __position.node, __v, __position.node);


	// All other cases:

	// Optimization to catch insert-equivalent -- save comparison results,
	// and we get this for free.
	if(_STL::less<unsigned short>()(__v.key, key(__after.node))) {
	  if (__position.node->_M_right == 0)
	    return insert(0, __position.node, __v, __position.node);
	  else
	    return insert(__after.node, __after.node, __v);
	} else {
	    return insertUnique(__v).first;
	}
      }

  } else if (__position.node == header.node) { // end()
    if (_STL::less<unsigned short>()(key(header.node->_M_right), __v.key))
      // pass along to _M_insert that it can skip comparing
      // v, Key ; since compare Key, v was true, compare v, Key must be false.
      return insert(0, header.node->_M_right, __v, __position.node); // Last argument only needs to be non-null
    else
      return insertUnique(__v).first;
  } else {
    Rva0093FD80Iterator __before = __position;
    --__before;

    bool __comp_v_pos = _STL::less<unsigned short>()(__v.key, key(__position.node));

    if (__comp_v_pos
      && _STL::less<unsigned short>()(key(__before.node), __v.key)) {

      if (__before.node->_M_right == 0)
        return insert(0, __before.node, __v, __before.node); // Last argument only needs to be non-null
      else
        return insert(__position.node, __position.node, __v);
    // first argument just needs to be non-null
    } else
      {
	// Does the insertion point fall immediately AFTER the hint?
	Rva0093FD80Iterator __after = __position;
	++__after;

	// Optimization to catch equivalent cases and avoid unnecessary comparisons
	bool __comp_pos_v = !__comp_v_pos;  // Stored this result earlier
	// If the earlier comparison was true, this comparison doesn't need to be
	// performed because it must be false.  However, if the earlier comparison
	// was false, we need to perform this one because in the equal case, both will
	// be false.
	if (!__comp_v_pos) __comp_pos_v = _STL::less<unsigned short>()(key(__position.node), __v.key);

	if ( (!__comp_v_pos) // comp_v_pos true implies comp_v_pos false
	     && __comp_pos_v
	     && (__after.node == header.node ||
	        _STL::less<unsigned short>()(__v.key, key(__after.node)))) {

	  if (__position.node->_M_right == 0)
	    return insert(0, __position.node, __v, __position.node);
	  else
	    return insert(__after.node, __after.node, __v);
	} else {
	  // Test for equivalent case
	  if (__comp_v_pos == __comp_pos_v)
	    return __position;
	  else
	    return insertUnique(__v).first;
	}
      }
  }
}

