    _STL::_Rb_tree_node_base *node = tree.header.node->_M_parent;
    while (node != 0)
    {
        if (!(static_cast<Rva0093DCE0Node *>(node)->value.key < key))
        {
            result = node;
            node = node->_M_left;
        }
        else
            node = node->_M_right;
    }
    if (result == tree.header.node || key < static_cast<Rva0093DCE0Node *>(result)->value.key)
    {
        Rva0093FD80Value value = {key, 0};
        Rva0093FD80Iterator position(result);
        position = insert(position, value);
        result = position.node;
    }
    return static_cast<Rva0093DCE0Node *>(result)->value.value;
}
